string makeLargestSpecial(string S) {

        if(S == "") return "";

        vector<string> v;
        int cnt = 0;
        for(int start = 0, i = 0; i < S.size(); i ++){
            cnt += (S[i] == '1' ? 1 : -1);
            if(!cnt){
                v.push_back("1" + makeLargestSpecial(S.substr(start + 1, i - start - 1)) + "0");
                start = i + 1;
            }
        }

        sort(v.begin(), v.end(), greater<string>());
        string res = "";
        for(const string& e: v) res += e;
        return res;
    }

int dfs(int n, int index, vector<bool>& used){

        if(index == n + 1) return 1;

        int res = 0;
        for(int num = 1; num <= n; num ++)
            if(!used[num] && (num % index == 0 || index % num == 0)){
                used[num] = true;
                res += dfs(n, index + 1, used);
                used[num] = false;
            }
        return res;
    }

