vector<int> grayCode(int n)
  {
    if (n == 1)
      return {0, 1};
    auto prev = grayCode(n - 1);
    auto ans = prev;

    for (int i = prev.size() - 1; i >= 0; --i)
    {
      int num = prev[i] + pow(2, n - 1);
      ans.push_back(num);
    }

    return ans;
  }

