int lps(string s)
{
  int n = s.size(), len = 0;
  vector<int> lps(n, 0);
  lps[0] = 0;

  int i = 1;
  while (i < n)
  {
    if (s[i] == s[len])
    {
      len++;
      lps[i] = len;
      i++;
    }
    else
    {
      if (len != 0)
        len = lps[len - 1];
      else
      {
        lps[i] = 0;
        i++;
      }
    }
  }
  return lps[n - 1];
}

void insert(stack<int> &s, int t)
{
  if (s.size() == 0 || s.top() < t)
    s.push(t);
  else
  {
    int temp = s.top();
    s.pop();
    insert(s, t);
    s.push(temp);
  }
}

bool dfs(bool graph[101][101], int curr, int V, int m, vector<int> &colors)
{
  if (curr == V)
    return true;

  for (int c = 1; c <= m; ++c)
  {
    int flag = 0;
    colors[curr] = c;

    for (int i = 0; i < V; ++i)
    {
      if (graph[curr][i] && colors[i] == c)
      {
        flag = 1;
        break;
      }
    }

    if (!flag)
    {
      if (dfs(graph, curr + 1, V, m, colors))
        return true;
    }

    colors[curr] = 0;
  }

  return false;
}
